namespace GeetaStudio.Api;

internal static class CustomerPage
{
    internal const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My account and household</title>
<style>body{font:17px system-ui;max-width:1000px;margin:auto;padding:24px;background:#f8f6ef;color:#272623}section{background:white;padding:20px;margin:16px 0;border:1px solid #aaa;border-radius:8px}label{display:inline-block;margin:8px}input,select,button{font:inherit;padding:8px;max-width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px;border-bottom:1px solid #ccc}#status{min-height:24px}</style>
<h1>My account and household</h1><p>Local account workspace. Test purchases make no real charge and grant fixture access only. Persistent child personalization is awaiting launch review; advertising profiles are disabled.</p>
<label>Workspace <input id="tenant" aria-label="Workspace identifier"></label><button id="load">Open account</button><p id="status" role="status" aria-live="polite"></p>
<section><h2>Account</h2><label>Display label <input id="display" maxlength="80"></label><label><input id="adult" type="checkbox"> I am an adult responsible for profiles I manage</label><button id="register">Create verified local account</button><div id="me"></div><button id="export">Download my data</button><button id="delete">Delete account</button><p>Deletion erases profile labels and progress. Minimal financial, consent and identity tombstone evidence remains for reconciliation. Transfer a shared household and reconcile active payments/work first.</p></section>
<section><h2>Household</h2><label>Label <input id="houseLabel" maxlength="80"></label><button id="house">Create household</button><label>Household <select id="household"></select></label><label>Adult account identifier <input id="inviteUser"></label><label>Role <select id="role"><option>Adult</option><option>Parent</option></select></label><button id="invite">Invite adult</button><button id="transfer">Transfer ownership</button><label>Invitation <input id="inviteId"></label><button id="accept">Accept my invitation</button></section>
<section><h2>Profiles and consent</h2><label>Profile label <input id="alias" maxlength="80"></label><label>Age band <select id="age"><option>Adult</option><option>Teen</option><option>Child</option></select></label><label>Language <input id="locale" value="en-IN"></label><button id="profileAdd">Add profile</button><label>Profile <select id="profile"></select></label><button id="profileDelete">Delete profile</button><label>Consent <select id="purpose"><option>Progress</option><option>Personalization</option></select></label><button id="consent">Allow for 30 days</button><button id="withdraw">Withdraw</button><label><input id="personalize" type="checkbox"> Personalization</label><button id="profileEdit">Save label, language and setting</button><div id="profiles"></div></section>
<section><h2>Reading progress</h2><label>Journey <input id="journey" value="geeta-reading"></label><label>Position <input id="position" type="number" min="0" max="1000000" value="0"></label><label><input id="bookmark" type="checkbox"> Bookmark</label><button id="progressLoad">Load synchronized progress</button><button id="progressSave">Save progress</button><div id="progress"></div></section>
<section><h2>Geeta+ and credits</h2><p>Customer credits are separate from provider spending budgets. Payment access is established only by verified server evidence. Expired, reserved and reversed credits cannot be spent again.</p><label>Test product <select id="product"></select></label><label>Acquisition <input id="acquisition" value="Unknown"></label><button id="buy">Create test purchase</button><div id="entitlements"></div><div id="wallet"></div><div id="orders"></div></section>
<section><h2>Reserved work</h2><label>Work identifier <input id="usage"></label><label>Credits <input id="credits" type="number" min="1" value="1"></label><button id="reserve">Reserve credits</button><div id="reservations"></div><p>Before dispatch you can cancel. Running or uncertain work settles only through its original trusted service receipt.</p></section>
<section><h2>Private payment notices</h2><p>Billing notices stay in this account. No email, SMS or marketing messages are sent.</p><div id="notices"></div></section>
<script>
const $=id=>document.getElementById(id);let profiles=[],progress=[];
function base(){return '/api/v1/customer/tenants/'+encodeURIComponent($('tenant').value.trim())}
async function api(path,body){const r=await fetch(base()+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-ContentOS-Staff':'1'}:{},body:body?JSON.stringify({operationId:crypto.randomUUID(),...body}):undefined});let x=await r.json();if(!r.ok)throw Error(x.error||'Request unavailable');return x}
async function run(f){try{$('status').textContent='Working…';await f();$('status').textContent='Saved.'}catch(e){$('status').textContent=e.message}}
function show(id,data){$(id).replaceChildren();const p=document.createElement('pre');p.textContent=JSON.stringify(data,null,2);$(id).append(p)}
function options(id,rows,label){const value=$(id).value;$(id).replaceChildren();for(const x of rows){const o=document.createElement('option');o.value=x.id;o.textContent=label(x);$(id).append(o)}if(rows.some(x=>x.id===value))$(id).value=value}
function table(id,rows,fields,actions=[]){const t=document.createElement('table'),h=t.insertRow();for(const [key,label]of fields){const th=document.createElement('th');th.textContent=label;h.append(th)}for(const x of rows){const row=t.insertRow();for(const [key,label]of fields)row.insertCell().textContent=x[key]??'Unavailable';for(const [label,fn]of actions){const b=document.createElement('button');b.textContent=label;b.onclick=()=>run(async()=>{await fn(x);await load()});row.insertCell().append(b)}}$(id).replaceChildren(t)}
async function load(){show('me',await api('/me'));options('household',await api('/households'),x=>x.label+' ('+x.role+')');profiles=await api('/profiles');options('profile',profiles,x=>x.alias+' ('+x.ageBand+')');show('profiles',profiles.map(x=>({label:x.alias,age:x.ageBand,personalization:x.personalization,advertising:x.advertisingProfiling})));options('product',await api('/products'),x=>x.key+' v'+x.version+' '+(x.priceMinor/100)+' '+x.currency+' — fixture');show('entitlements',await api('/entitlements'));const wallet=await api('/wallet');show('wallet',{available:wallet.available,reserved:wallet.reserved,consumed:wallet.consumed,reversed:wallet.reversed,expired:wallet.expired});table('orders',await api('/orders'),[['id','Order'],['state','State'],['provider','Original provider'],['refundedMinor','Refund (minor units)']],[['Submit once',x=>api('/orders/'+x.id+'/submit',{})],['Reconcile',x=>api('/orders/'+x.id+'/reconcile',{})],['Cancel',x=>api('/orders/'+x.id+'/change',{action:'Cancel',amountMinor:0})],['Request full remaining refund',x=>api('/orders/'+x.id+'/change',{action:'Refund',amountMinor:x.priceMinor-x.refundedMinor})]]);table('reservations',await api('/reservations'),[['usageKey','Work'],['amount','Credits'],['state','State'],['consumed','Consumed']],[['Cancel before dispatch',x=>api('/reservations/'+x.id+'/cancel',{})]]);table('notices',await api('/notifications'),[['kind','Notice'],['state','Receipt']],[['Receive in inbox',x=>api('/notifications/'+x.id+'/deliver',{})]])}
$('load').onclick=()=>run(load);$('register').onclick=()=>run(async()=>{await api('/register',{displayName:$('display').value});await load()});$('house').onclick=()=>run(async()=>{await api('/households',{label:$('houseLabel').value});await load()});$('invite').onclick=()=>run(async()=>{show('profiles',{invitation:await api('/households/'+$('household').value+'/invite',{userId:$('inviteUser').value,role:$('role').value})})});$('transfer').onclick=()=>run(async()=>{await api('/households/'+$('household').value+'/transfer',{userId:$('inviteUser').value});await load()});$('accept').onclick=()=>run(async()=>{await api('/invites/'+$('inviteId').value+'/accept',{});await load()});$('profileAdd').onclick=()=>run(async()=>{await api('/profiles',{householdId:$('household').value,alias:$('alias').value,ageBand:$('age').value,locale:$('locale').value});await load()});$('profileEdit').onclick=()=>run(async()=>{const p=profiles.find(x=>x.id===$('profile').value);await api('/profiles/'+p.id+'/edit',{rowVersion:p.rowVersion,alias:$('alias').value||p.alias,locale:$('locale').value,personalization:$('personalize').checked});await load()});
for(const [id,granted]of [['consent',true],['withdraw',false]])$(id).onclick=()=>run(async()=>{await api('/consents',{profileId:$('profile').value,purpose:$('purpose').value,granted,expiresUtc:new Date(Date.now()+30*86400000).toISOString(),evidence:'manual:local-account-consent'});await load()});
async function loadProgress(){progress=await api('/profiles/'+$('profile').value+'/progress');show('progress',progress)}$('progressLoad').onclick=()=>run(loadProgress);$('progressSave').onclick=()=>run(async()=>{await loadProgress();const old=progress.find(x=>x.key===$('journey').value);await api('/profiles/'+$('profile').value+'/progress',{rowVersion:old?.rowVersion||'',key:$('journey').value,position:Number($('position').value),bookmark:$('bookmark').checked});await loadProgress()});$('buy').onclick=()=>run(async()=>{await api('/checkout',{productId:$('product').value,acquisition:$('acquisition').value});await load()});$('reserve').onclick=()=>run(async()=>{await api('/reservations',{profileId:$('profile').value,usageKey:$('usage').value,amount:Number($('credits').value)});await load()});$('profileDelete').onclick=()=>run(async()=>{if(!confirm('Erase this profile label and synchronized progress?'))return;await api('/profiles/'+$('profile').value+'/delete',{});await load()});$('delete').onclick=()=>run(async()=>{if(!confirm('Erase this account’s profile data and disable all sign-in bindings?'))return;await api('/delete',{});show('me',{state:'Deleted'})});$('export').onclick=()=>run(async()=>{const data=await api('/export'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='my-account.json';a.click();URL.revokeObjectURL(url)});
</script></html>
""";
    internal const string AdminHtml = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account controls</title><style>body{font:17px system-ui;max-width:900px;margin:auto;padding:24px}input,select,button{font:inherit;padding:8px;margin:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>Account controls</h1><p>Private test catalog, provider routes and service receipts. No live payment provider is qualified. New routes do not migrate existing customers or subscriptions.</p><label>Workspace <input id="tenant"></label><button id="load">Inspect providers and routes</button><label>Evidence action <select id="action"><option value="products">Product version</option><option value="routes">Route version</option><option value="grants">Credit grant</option><option value="payment-events">Signed test payment event</option></select></label><label>Evidence file <input id="file" type="file" accept=".json"></label><button id="save">Import evidence</button><p id="status" role="status" aria-live="polite"></p><pre id="result"></pre><p>Use the local runbook for exact route control and original-work dispatch/settlement requests. Account users cannot grant credits, report payment success, or settle running work.</p><script>
const $=id=>document.getElementById(id);async function api(path,body){const r=await fetch('/api/v1/customer-admin/tenants/'+encodeURIComponent($('tenant').value.trim())+'/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-ContentOS-Staff':'1'}:{},body:body?JSON.stringify(body):undefined}),x=await r.json();if(!r.ok)throw Error(x.error||'Request rejected');return x}async function run(f){try{$('status').textContent='Working…';$('result').textContent=JSON.stringify(await f(),null,2);$('status').textContent='Done.'}catch(e){$('status').textContent=e.message}}$('load').onclick=()=>run(async()=>({providers:await api('providers'),routes:await api('routes')}));$('save').onclick=()=>run(async()=>{const f=$('file').files[0];if(!f||f.size>65536)throw Error('Select an evidence file of at most 64 KB.');const data=JSON.parse(await f.text());if($('action').value!=='payment-events')data.operationId||=crypto.randomUUID();return api($('action').value,data)});
</script></html>
""";
}
